function ocenPogode(temperatura) {
  if (temperatura < 10) {
    return "zimno";
  } else if (temperatura < 25) {
    return "przyjemnie";
  } else {
    return "goraco";
  }
}

console.log(ocenPogode(5));  // "zimno"
console.log(ocenPogode(20)); // "przyjemnie"
console.log(ocenPogode(30)); // "goraco"

function czyPelnoletni(wiek) {
  if (wiek >= 18) {
    return true;
  } else {
    return false;
  }
}

console.log(czyPelnoletni(20)); // true
console.log(czyPelnoletni(15)); // false

function sprawdzHaslo(haslo) {
  if (haslo.length < 8) {
    return "za krotkie";
  }
  return "OK";
}

console.log(sprawdzHaslo("abc"));         // "za krotkie"
console.log(sprawdzHaslo("bezpieczneHaslo")); // "OK"

function znakLiczby(n) {
  if (n > 0) {
    return "dodatnia";
  } else if (n < 0) {
    return "ujemna";
  } else {
    return "zero";
  }
}

console.log(znakLiczby(5));  // "dodatnia"
console.log(znakLiczby(-3)); // "ujemna"
console.log(znakLiczby(0));  // "zero"

function czyPelnoletni(wiek) {
  return wiek >= 18 ? true : false;
}

console.log(czyPelnoletni(20)); // true
console.log(czyPelnoletni(15)); // false

const godzina = 14;
const poraDnia = godzina < 18 ? "dzien" : "wieczor";
console.log(poraDnia); // "dzien"

function ocenaLiterowa(ocena) {
  return ocena >= 90 ? "A" : ocena >= 75 ? "B" : ocena >= 50 ? "C" : "D";
}

console.log(ocenaLiterowa(95)); // "A"
console.log(ocenaLiterowa(80)); // "B"
console.log(ocenaLiterowa(60)); // "C"
console.log(ocenaLiterowa(30)); // "D"

function zarejestrujUzytkownika(dane) {
  if (!dane) return { blad: "Brak danych" };
  if (!dane.email) return { blad: "Brak emaila" };
  if (!dane.haslo) return { blad: "Brak hasla" };

  return { sukces: true };
}

console.log(zarejestrujUzytkownika(null)); // { blad: 'Brak danych' }
console.log(zarejestrujUzytkownika({ email: "a@b.pl", haslo: "12345678" })); // { sukces: true }

function policzRabat(cena, kodRabatowy) {
  if (!kodRabatowy) return cena;
  return cena * 0.9;
}

console.log(policzRabat(100, null)); // 100
console.log(policzRabat(100, "RABAT10")); // 90

function sprawdzZagniezdzoneZle(n) {
  if (n > 0) {
    if (n % 2 === 0) {
      if (n > 10) {
        return "spelnia wszystkie warunki";
      } else {
        return "za mala";
      }
    } else {
      return "nieparzysta";
    }
  } else {
    return "nie dodatnia";
  }
}

// wersja guard clause (czytelniejsza):
function sprawdzGuardClause(n) {
  if (n <= 0) return "nie dodatnia";
  if (n % 2 !== 0) return "nieparzysta";
  if (n <= 10) return "za mala";
  return "spelnia wszystkie warunki";
}

console.log(sprawdzZagniezdzoneZle(12)); // "spelnia wszystkie warunki"
console.log(sprawdzGuardClause(12));     // "spelnia wszystkie warunki" - ten sam wynik, czytelniejszy kod

function kategoriaBmi(bmi) {
  if (bmi < 18.5) {
    return "niedowaga";
  } else if (bmi < 25) {
    return "norma";
  } else if (bmi < 30) {
    return "nadwaga";
  } else {
    return "otylosc";
  }
}

console.log(kategoriaBmi(17));   // "niedowaga"
console.log(kategoriaBmi(22));   // "norma"
console.log(kategoriaBmi(27));   // "nadwaga"
console.log(kategoriaBmi(33));   // "otylosc"

function maxZDwoch(a, b) {
  return a > b ? a : b;
}

console.log(maxZDwoch(5, 10)); // 10
console.log(maxZDwoch(20, 3)); // 20

function formatujStatus(aktywny) {
  return aktywny ? "OK" : "BRAK";
}

console.log(formatujStatus(true));  // "OK"
console.log(formatujStatus(false)); // "BRAK"

function walidujWiek(wiek) {
  if (wiek < 0) return "Wiek nie moze byc ujemny";
  if (wiek > 120) return "Wiek nierealistyczny";
  return "OK";
}

console.log(walidujWiek(-5));  // "Wiek nie moze byc ujemny"
console.log(walidujWiek(150)); // "Wiek nierealistyczny"
console.log(walidujWiek(30));  // "OK"

function obliczOplateParkingowa(godziny) {
  if (godziny <= 1) {
    return 0;
  } else {
    return (godziny - 1) * 5;
  }
}

console.log(obliczOplateParkingowa(1)); // 0
console.log(obliczOplateParkingowa(3)); // 10

function sprawdzTrojkat(a, b, c) {
  if (a >= b + c) return false;
  if (b >= a + c) return false;
  if (c >= a + b) return false;
  return true;
}

console.log(sprawdzTrojkat(3, 4, 5));  // true
console.log(sprawdzTrojkat(1, 1, 10)); // false

const uzytkownik = { imie: "Jan", rola: "admin" };
const opis = `${uzytkownik.imie} (${uzytkownik.rola === "admin" ? "Administrator" : "Uzytkownik"})`;
console.log(opis); // "Jan (Administrator)"

function ocenSzybkoscInternetu(mbps) {
  return mbps < 10 ? "wolne" : mbps < 50 ? "srednie" : mbps < 200 ? "szybkie" : "bardzo szybkie";
}

console.log(ocenSzybkoscInternetu(5));   // "wolne"
console.log(ocenSzybkoscInternetu(300)); // "bardzo szybkie"

function pobierzZnizke(wiek, jestStudentem) {
  if (wiek < 18 || wiek >= 65) {
    return 50;
  } else if (jestStudentem) {
    return 20;
  } else {
    return 0;
  }
}

console.log(pobierzZnizke(70, false)); // 50
console.log(pobierzZnizke(25, true));  // 20
console.log(pobierzZnizke(30, false)); // 0

function sprawdzSilaHasla(haslo) {
  if (haslo.length < 8) return "slabe";
  if (!/[A-Z]/.test(haslo)) return "srednie";
  return "silne";
}

console.log(sprawdzSilaHasla("abc"));         // "slabe"
console.log(sprawdzSilaHasla("dlugiehaslo")); // "srednie"
console.log(sprawdzSilaHasla("DlugieHaslo"));  // "silne"

function formatujCene(cena) {
  if (cena === 0) {
    return "Za darmo";
  }
  return `${cena} zl`;
}

console.log(formatujCene(0));   // "Za darmo"
console.log(formatujCene(50));  // "50 zl"

function czyRokPrzestepny(rok) {
  if (rok % 4 === 0 && (rok % 100 !== 0 || rok % 400 === 0)) {
    return true;
  }
  return false;
}

console.log(czyRokPrzestepny(2024)); // true
console.log(czyRokPrzestepny(2023)); // false
console.log(czyRokPrzestepny(1900)); // false
console.log(czyRokPrzestepny(2000)); // true

function pobierzPozdrowienie(godzina) {
  if (godzina >= 5 && godzina <= 11) {
    return "Dzien dobry";
  } else if (godzina >= 12 && godzina <= 17) {
    return "Dzien dobry (popoludnie)";
  } else if (godzina >= 18 && godzina <= 21) {
    return "Dobry wieczor";
  } else {
    return "Dobranoc";
  }
}

console.log(pobierzPozdrowienie(8));  // "Dzien dobry"
console.log(pobierzPozdrowienie(23)); // "Dobranoc"

const produkty = [{ nazwa: "A", cena: 0 }, { nazwa: "B", cena: 50 }];
const opisy = produkty.map(p => `${p.nazwa}: ${p.cena === 0 ? "Za darmo" : p.cena + " zl"}`);
console.log(opisy); // ['A: Za darmo', 'B: 50 zl']

function sprawdzDostepnosc(magazyn) {
  if (magazyn.ilosc === 0) return "brak w magazynie";
  if (magazyn.ilosc < 5) return "malo sztuk";
  return "dostepny";
}

console.log(sprawdzDostepnosc({ ilosc: 0 })); // "brak w magazynie"
console.log(sprawdzDostepnosc({ ilosc: 3 })); // "malo sztuk"
console.log(sprawdzDostepnosc({ ilosc: 50 })); // "dostepny"

function porownajLiczby(a, b) {
  if (a < b) {
    return -1;
  } else if (a > b) {
    return 1;
  } else {
    return 0;
  }
}

console.log(porownajLiczby(3, 5)); // -1
console.log(porownajLiczby(5, 3)); // 1
console.log(porownajLiczby(5, 5)); // 0

function bezpiecznyDostep(obiekt, klucz) {
  if (!obiekt) return null;
  return obiekt[klucz] ?? "brak wartosci";
}

console.log(bezpiecznyDostep(null, "a"));           // null
console.log(bezpiecznyDostep({ a: 1 }, "a"));       // 1
console.log(bezpiecznyDostep({ a: 1 }, "b"));       // "brak wartosci"

function obliczPodatek(dochod) {
  if (dochod <= 120000) {
    return dochod * 0.12;
  } else {
    return dochod * 0.12 + (dochod - 120000) * 0.32;
  }
}

console.log(obliczPodatek(100000)); // 12000
console.log(obliczPodatek(150000)); // 24000

function sprawdzTypDanych(wartosc) {
  if (wartosc === null) return "null";
  if (Array.isArray(wartosc)) return "tablica";
  return typeof wartosc;
}

console.log(sprawdzTypDanych(null));      // "null"
console.log(sprawdzTypDanych([1, 2]));    // "tablica"
console.log(sprawdzTypDanych("tekst"));   // "string"

